FormulaFieldDefinitions.FormulaFieldDefinition:
currencyVar caramt :=0 ;
if {@Group1}='M' then
    caramt:=abs({@CrdAmt});

if {@GrossProfit} < 0  then
    IF caramt <0 THEN
        ABS({@GrossProfit})+{@TradingSumCr} + {@CrdAmt}
    ELSE
        ABS({@GrossProfit})+{@TradingSumCr} + {@CrdAmt}

ELSE    
         if {@CrdAmt}<0 then
             {@TradingSumCr}
         else
              {@TradingSumCr}+caramt

currencyVar caramt :=0 ;
if {@Group1}='M' then
    caramt:=abs({@CrdAmt});

if {@GrossProfit} > 0  then
    ABS({@GrossProfit})+{@TradingSumDr}
ELSE    
         if {@CrdAmt}>0 then
             {@TradingSumDr}
         else
              {@TradingSumDr}+caramt

